extracted_python_code:
customer_success_rate = Customers.WHERE(
    COUNT(transactions_made) >= 5
).CALCULATE(
    customer_name=name,
    success_rate=(100.0 * COUNT(transactions_made.WHERE(LOWER(status) == 'success')) / COUNT(transactions_made))
).ORDER_BY(success_rate.ASC())

result = Broker.CALCULATE(
    num_customers = COUNT(
        Customers.WHERE(
            ENDSWITH(email, '.com') & 
            HAS(
                transactions_made.WHERE(
                    CONTAINS(ticker.symbol, 'AMZN') |
                    CONTAINS(ticker.symbol, 'AAPL') |
                    CONTAINS(ticker.symbol, 'GOOGL') |
                    CONTAINS(ticker.symbol, 'META') |
                    CONTAINS(ticker.symbol, 'NFLX')
                )
            ) == 1
        )
    )
)

active_customers_since_2023 = Customers.WHERE(
    (LOWER(status) == 'active') & (join_date >= "2023-01-01")
)
tac_by_country = active_customers_since_2023.PARTITION(
    name="country_groups", by=country
).CALCULATE(
    country=country,
    tac_count=COUNT(Customers)
)

recent_buy_transactions = Transactions.WHERE(
    (LOWER(transaction_type) == 'buy') & 
    (DATEDIFF("days", date_time, DATETIME('now')) <= 10)
)

transaction_info = recent_buy_transactions.CALCULATE(
    ticker_symbol=ticker.symbol
)

top_2_bought_stocks = transaction_info.PARTITION(
    name="ticker_groups", by=ticker_symbol
).CALCULATE(
    ticker_symbol=ticker_symbol,
    num_buy_transactions=COUNT(Transactions)
).TOP_K(2, by=num_buy_transactions.DESC())

# Filter for customers who joined in 2022 and have at least one transaction.
customers_2022_with_transactions = Customers.WHERE(
    (YEAR(join_date) == 2022) & (HAS(transactions_made) == 1)
)

# Partition the filtered customers by country and calculate the Activity Ratio for each.
activity_ratio_by_country = customers_2022_with_transactions.PARTITION(
    name="country_groups", by=(country)
).CALCULATE(
    country=country,
    AR=(
        100.0 * SUM(IFF(LOWER(Customers.status) == 'active', 1, 0))
    ) / COUNT(Customers)
)

num_customers_by_name_and_state = Broker.CALCULATE(
    num_customers=COUNT(
        Customers.WHERE(
            (STARTSWITH(LOWER(name), 'j') | ENDSWITH(LOWER(name), 'ez')) &
            ENDSWITH(LOWER(state), 'a')
        )
    )
)

