extracted_python_code:
current_month_start_date = DATETIME('now', 'start of month')
six_months_ago_start_date = DATETIME(current_month_start_date, '-6 months')

sales_metrics = Dealership.Sales.WHERE(
    (sale_date >= six_months_ago_start_date) & (sale_date < current_month_start_date)
).CALCULATE(
    sale_month_val=DATETIME(sale_date, 'start of month')
).PARTITION(
    name='sales_by_month', by=sale_month_val
).CALCULATE(
    month=sale_month_val,
    PMSPS=COUNT(
        Sales.WHERE(
            (YEAR(salesperson.hire_date) >= 2022) & (YEAR(salesperson.hire_date) <= 2023)
        )
    ),
    PMSR=DEFAULT_TO(SUM(
        Sales.WHERE(
            (YEAR(salesperson.hire_date) >= 2022) & (YEAR(salesperson.hire_date) <= 2023)
        ).sale_price
    ), 0.0)
).ORDER_BY(month.ASC())

